using System;\nusing NUnit.Framework;\nusing RestSharp;\nusing TechTalk.SpecFlow;\nusing AutomationFramework.API.BusinessLogic;\nusing Newtonsoft.Json;\nusing Serilog;\n\n[Binding]\npublic class PetStoreCRUDSteps\n{\n    private readonly ScenarioContext _scenarioContext;\n    private readonly PetBusinessLogic _petBusinessLogic;\n    private RestResponse _response;\n    private long _petId;\n\n    public PetStoreCRUDSteps(ScenarioContext scenarioContext)\n    {\n        _scenarioContext = scenarioContext;\n        _petBusinessLogic = new PetBusinessLogic(\"https://petstore.swagger.io\");\n    }\n\n    [Given(\"the API endpoint is \\\"(.*)\\\"\")]\n    public void GivenTheApiEndpointIs(string endpoint)\n    {\n        _scenarioContext[\"Endpoint\"] = endpoint;\n        Log.Information(\"Endpoint set to: {Endpoint}\", endpoint);\n    }\n\n    [When(\"I send a POST request with the following data:\")]\n    public void WhenISendAPostRequestWithTheFollowingData(Table table)\n    {\n        var endpoint = _scenarioContext[\"Endpoint\"].ToString();\n        var requestData = new\n        {\n            name = table.Rows[0][\"name\"],\n            status = table.Rows[0][\"status\"],\n            category = table.Rows[0][\"category\"],\n            tags = table.Rows[0][\"tags\"]\n        };\n\n        _response = _petBusinessLogic.CreatePet(requestData.name, requestData.status, requestData.category, requestData.tags);\n        _scenarioContext[\"Response\"] = _response;\n\n        Log.Information(\"POST request sent to: {Endpoint} with data: {RequestData}\", endpoint, JsonConvert.SerializeObject(requestData));\n    }\n\n    [Then(\"the response status code should be (.*)\")]\n    public void ThenTheResponseStatusCodeShouldBe(int expectedStatusCode)\n    {\n        var response = _scenarioContext[\"Response\"] as RestResponse;\n        Assert.That((int)response.StatusCode, Is.EqualTo(expectedStatusCode), \"Expected status code does not match.\");\n        Log.Information(\"Response status code validated: {StatusCode}\", response.StatusCode);\n    }\n\n    [Then(\"the response body should contain the pet ID\")]\n    public void ThenTheResponseBodyShouldContainThePetId()\n    {\n        var response = _scenarioContext[\"Response\"] as RestResponse;\n        Assert.That(response.Content, Does.Contain(\"id\"), \"Response body does not contain the pet ID.\");\n        Log.Information(\"Response body contains the pet ID.\");\n    }\n\n    [When(\"I send a GET request\")]\n    public void WhenISendAGet